import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'support/oracle_compare.dart';

/// Per-language floor, in percent, of non-whitespace characters whose colour
/// class and font style equal what shiki 4.4.3 (dsh's configuration) reports on
/// the committed samples (test/fixtures/samples, oracle in test/fixtures/oracle,
/// regenerated by tool/highlight/oracle.mjs). Measured: 100.0 everywhere; the
/// floors leave room only for a grammar or SDK update, not for regressions.
const Map<String, double> floors = {
  // Bar: >= 98.
  'typescript': 99.0,
  'shellscript': 99.0,
  'json': 99.0,
  'python': 99.0,
  'markdown': 99.0,
  'yaml': 99.0,
  'css': 99.0,
  'html': 99.0,
  'dart': 99.0,
  // Bar: >= 95.
  'scss': 99.0,
  'go': 99.0,
  'rust': 99.0,
  'java': 99.0,
  'c': 99.0,
  'cpp': 99.0,
  'csharp': 99.0,
  'kotlin': 99.0,
  'swift': 99.0,
  'ruby': 99.0,
  'php': 99.0,
  'sql': 99.0,
  'xml': 99.0,
  'toml': 99.0,
  'ini': 99.0,
  'diff': 99.0,
  'lua': 99.0,
  'make': 99.0,
};

void main() {
  test('every sample directory has a floor and an oracle', () {
    final samples = Directory('test/fixtures/samples')
        .listSync()
        .whereType<Directory>()
        .map((d) => d.uri.pathSegments[d.uri.pathSegments.length - 2])
        .toSet();
    expect(samples, floors.keys.toSet());
    for (final g in samples) {
      expect(
        File('test/fixtures/oracle/$g.json').existsSync(),
        isTrue,
        reason: g,
      );
    }
  });

  for (final entry in floors.entries) {
    test('${entry.key}: matches shiki on the samples', () async {
      final engine = await engineFor(entry.key);
      final report = compareLanguage(engine, entry.key);
      printOnFailure(report.mismatches.take(40).join('\n'));
      // ignore: avoid_print
      print(
        'oracle ${entry.key.padRight(12)} '
        '${report.percent.toStringAsFixed(2)}% '
        '(${report.matched}/${report.total} chars, ${report.lines} lines)',
      );
      expect(report.structural, isEmpty);
      expect(report.percent, greaterThanOrEqualTo(entry.value));
      expect(engine.degradedPatternCount, 0);
    });
  }
}
